CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),issuer text NOT NULL CHECK(length(issuer)>0),subject text NOT NULL CHECK(length(subject)>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(issuer,subject));
CREATE TABLE IF NOT EXISTS memberships (tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,identity_id));
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES identities(id),title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 256),kind text NOT NULL CHECK(length(kind) BETWEEN 1 AND 64),current_revision bigint NOT NULL DEFAULT 1 CHECK(current_revision>=1),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE INDEX IF NOT EXISTS projects_tenant_updated ON projects(tenant_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS asset_metadata (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,project_id uuid NOT NULL,storage_key text NOT NULL CHECK(length(storage_key)>0),media_type text NOT NULL CHECK(length(media_type)>0),sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),size_bytes bigint NOT NULL CHECK(size_bytes>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),CONSTRAINT asset_same_tenant_project FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS asset_metadata_project ON asset_metadata(tenant_id,project_id,created_at DESC);
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
ALTER TABLE identities ENABLE ROW LEVEL SECURITY;
ALTER TABLE identities FORCE ROW LEVEL SECURITY;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE projects FORCE ROW LEVEL SECURITY;
ALTER TABLE asset_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE asset_metadata FORCE ROW LEVEL SECURITY;
